        self.login_page = True
        self.username = None
        self.password = None

    def login(self):
        if self.login_page:
            self.username = input("Enter your username: ")
            self.password = input("Enter your password: ")
            self.check_credentials()
        else:
            print("You are already logged in.")

    def check_credentials(self):
